-- M12：修正样例模板引用，补齐财务独立权限。已执行的V47、V48保持原样。

UPDATE gl_standard_preset SET payload='{"rows":[{"code":"cash","name":"货币资金","formula":"CASH_QM()","bold":false,"indent":0},{"code":"ar","name":"应收账款","formula":"QM(1122,D)+QM(2203,D)-QM(1231)","bold":false,"indent":0},{"code":"prepaid","name":"预付款项","formula":"QM(1123,D)+QM(2202,D)","bold":false,"indent":0},{"code":"inventory","name":"存货","formula":"QM(1401)+QM(1402)+QM(1403)+QM(1404)+QM(1405)+QM(1406)+QM(1407)+QM(1408)+QM(1411)+QM(1421)+CAT(cost)-QM(1471)","bold":false,"indent":0},{"code":"fixed","name":"固定资产及在建工程","formula":"QM(1601)+QM(1604)+QM(1605)+QM(1606)-QM(1602)","bold":false,"indent":0},{"code":"intangible","name":"无形资产及长期待摊费用","formula":"QM(1701)+QM(1801)-QM(1702)","bold":false,"indent":0},{"code":"other_assets","name":"其他资产（按财务口径细分）","formula":"CAT(asset)+CAT(cost)+CAT(common,D)+QM(1122,C)+QM(1123,C)+QM(2202,D)+QM(2203,D)+QM(2221,D)-R(cash)-R(ar)-R(prepaid)-R(inventory)-R(fixed)-R(intangible)","bold":false,"indent":0},{"code":"assets","name":"资产总计","formula":"R(cash)+R(ar)+R(prepaid)+R(inventory)+R(fixed)+R(intangible)+R(other_assets)","bold":true,"indent":0},{"code":"ap","name":"应付账款","formula":"QM(2202,C)+QM(1123,C)","bold":false,"indent":0},{"code":"advance","name":"预收款项","formula":"QM(2203,C)+QM(1122,C)","bold":false,"indent":0},{"code":"tax","name":"应交税费","formula":"QM(2221,C)","bold":false,"indent":0},{"code":"other_liabilities","name":"其他负债","formula":"CAT(liability)+CAT(common,C)+QM(1122,C)+QM(1123,C)+QM(2202,D)+QM(2203,D)+QM(2221,D)-R(ap)-R(advance)-R(tax)","bold":false,"indent":0},{"code":"liabilities","name":"负债合计","formula":"R(ap)+R(advance)+R(tax)+R(other_liabilities)","bold":true,"indent":0},{"code":"capital","name":"实收资本及资本公积","formula":"QM(4001)+QM(4002)","bold":false,"indent":0},{"code":"retained","name":"本年利润及未分配利润","formula":"QM(4103)+QM(4104)+SY()","bold":false,"indent":0},{"code":"other_equity","name":"其他所有者权益","formula":"CAT(equity)-QM(4103)-QM(4104)-R(capital)","bold":false,"indent":0},{"code":"equity","name":"所有者权益合计","formula":"R(capital)+R(retained)+R(other_equity)","bold":true,"indent":0},{"code":"liability_equity","name":"负债和所有者权益总计","formula":"R(liabilities)+R(equity)","bold":true,"indent":0}],"checks":[{"name":"资产负债平衡","left":"R(assets)","right":"R(liability_equity)"}]}' WHERE standard='enterprise' AND kind='statement' AND code='balance_sheet';

UPDATE gl_standard_preset SET payload='{"rows":[{"code":"revenue","name":"营业收入","formula":"(DF(6001)-JF(6001))+(DF(6051)-JF(6051))","bold":false,"indent":0},{"code":"cost","name":"营业成本","formula":"(JF(6401)-DF(6401))+(JF(6402)-DF(6402))","bold":false,"indent":0},{"code":"gross_profit","name":"毛利","formula":"R(revenue)-R(cost)","bold":true,"indent":0},{"code":"tax_surcharge","name":"税金及附加","formula":"(JF(6403)-DF(6403))","bold":false,"indent":0},{"code":"selling","name":"销售费用","formula":"(JF(6601)-DF(6601))","bold":false,"indent":0},{"code":"management","name":"管理费用","formula":"(JF(6602)-DF(6602))","bold":false,"indent":0},{"code":"finance","name":"财务费用","formula":"(JF(6603)-DF(6603))","bold":false,"indent":0},{"code":"other_profit","name":"其他损益（按财务口径细分）","formula":"PL_NET()-R(gross_profit)+R(tax_surcharge)+R(selling)+R(management)+R(finance)","bold":false,"indent":0},{"code":"net_profit","name":"净利润","formula":"R(gross_profit)-R(tax_surcharge)-R(selling)-R(management)-R(finance)+R(other_profit)","bold":true,"indent":0}],"checks":[{"name":"损益发生一致","left":"R(net_profit)","right":"PL_NET()"}]}' WHERE standard='enterprise' AND kind='statement' AND code='income_statement';

UPDATE gl_standard_preset SET payload='{"rows":[{"code":"C01","name":"销售商品、提供劳务收到的现金","formula":"XJ(C01)","bold":false,"indent":1},{"code":"C02","name":"收到的税费返还","formula":"XJ(C02)","bold":false,"indent":1},{"code":"C03","name":"收到其他与经营活动有关的现金","formula":"XJ(C03)","bold":false,"indent":1},{"code":"C04","name":"购买商品、接受劳务支付的现金","formula":"XJ(C04)","bold":false,"indent":1},{"code":"C05","name":"支付给职工以及为职工支付的现金","formula":"XJ(C05)","bold":false,"indent":1},{"code":"C06","name":"支付的各项税费","formula":"XJ(C06)","bold":false,"indent":1},{"code":"C07","name":"支付其他与经营活动有关的现金","formula":"XJ(C07)","bold":false,"indent":1},{"code":"I01","name":"收回投资收到的现金","formula":"XJ(I01)","bold":false,"indent":1},{"code":"I02","name":"取得投资收益收到的现金","formula":"XJ(I02)","bold":false,"indent":1},{"code":"I03","name":"处置长期资产收回的现金净额","formula":"XJ(I03)","bold":false,"indent":1},{"code":"I04","name":"收到其他与投资活动有关的现金","formula":"XJ(I04)","bold":false,"indent":1},{"code":"I05","name":"购建长期资产支付的现金","formula":"XJ(I05)","bold":false,"indent":1},{"code":"I06","name":"投资支付的现金","formula":"XJ(I06)","bold":false,"indent":1},{"code":"I07","name":"支付其他与投资活动有关的现金","formula":"XJ(I07)","bold":false,"indent":1},{"code":"F01","name":"吸收投资收到的现金","formula":"XJ(F01)","bold":false,"indent":1},{"code":"F02","name":"取得借款收到的现金","formula":"XJ(F02)","bold":false,"indent":1},{"code":"F03","name":"收到其他与筹资活动有关的现金","formula":"XJ(F03)","bold":false,"indent":1},{"code":"F04","name":"偿还债务支付的现金","formula":"XJ(F04)","bold":false,"indent":1},{"code":"F05","name":"分配股利、利润或偿付利息支付的现金","formula":"XJ(F05)","bold":false,"indent":1},{"code":"F06","name":"支付其他与筹资活动有关的现金","formula":"XJ(F06)","bold":false,"indent":1},{"code":"operating_net","name":"经营活动现金流量净额","formula":"R(C01)+R(C02)+R(C03)-(R(C04)+R(C05)+R(C06)+R(C07))","bold":true,"indent":0},{"code":"investing_net","name":"投资活动现金流量净额","formula":"R(I01)+R(I02)+R(I03)+R(I04)-(R(I05)+R(I06)+R(I07))","bold":true,"indent":0},{"code":"financing_net","name":"筹资活动现金流量净额","formula":"R(F01)+R(F02)+R(F03)-(R(F04)+R(F05)+R(F06))","bold":true,"indent":0},{"code":"net_change","name":"现金及现金等价物净增加额","formula":"R(operating_net)+R(investing_net)+R(financing_net)","bold":true,"indent":0},{"code":"opening_cash","name":"期初现金及现金等价物余额","formula":"CASH_QC()","bold":false,"indent":0},{"code":"closing_cash","name":"期末现金及现金等价物余额","formula":"CASH_QM()","bold":true,"indent":0}],"checks":[{"name":"现金流量勾稽","left":"R(net_change)","right":"R(closing_cash)-R(opening_cash)"}]}' WHERE standard='enterprise' AND kind='statement' AND code='cash_flow';

